'use strict';
const STORAGE_KEY='briefboard-crusher-v1';
const STATUSES=['Backlog','Ready','In Progress','Review','Done'];
const ICONS={
 logo:'<rect x="4" y="3" width="6" height="8" rx="1"/><rect x="14" y="3" width="6" height="13" rx="1"/><rect x="4" y="15" width="6" height="6" rx="1"/><path d="M14 20h6"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 tree:'<path d="M5 3v14a3 3 0 0 0 3 3h2M5 9h5"/><rect x="11" y="5" width="10" height="7" rx="1"/><rect x="11" y="16" width="10" height="6" rx="1"/>',
 board:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16M15 4v16M5 9h2M11 12h2M17 8h2"/>',
 timeline:'<path d="M4 3v18h17M8 7h7M11 12h9M7 17h6"/>',
 people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',
 film:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M7 5v14M17 5v14M3 10h4M3 14h4M17 10h4M17 14h4"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 12h8M8 16h6"/>',
 folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 chevron:'<path d="m7 10 5 5 5-5"/>',
 right:'<path d="m9 5 7 7-7 7"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 cloud:'<path d="M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5 5 0 0 1 1 11M8 16l3 3 5-6"/>',
 link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0" transform="translate(1 0) scale(.9)"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',
 brush:'<path d="m14 4 6-2-2 6-8 8-4-4zM5 15a3 3 0 0 1 4 4c-1 2-6 2-6 2s0-5 2-6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
 shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6"/>',
 flag:'<path d="M5 22V3h13l-2 4 2 4H5"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
 more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
 reset:'<path d="M3 10a9 9 0 1 1 1 8M3 3v7h7"/>',
 expand:'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/>'
};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.file}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const slug=v=>String(v).toLowerCase().replaceAll(' ','-');
let state=clone(DEFAULT_STATE), importDraft=null, importing=false, storageOk=true, activeModal=null, lastFocus=null;
let toastTimer;
function taskById(id){return state.tasks.find(t=>t.id===id);}
function children(id){return state.tasks.filter(t=>t.parent===id);}
function descendants(id){const out=[];const visit=(n,seen=new Set())=>{if(seen.has(n))return;seen.add(n);for(const t of children(n)){out.push(t);visit(t.id,seen);}};visit(id);return out;}
function leaves(){return state.tasks.filter(t=>t.kind!=='group'&&!children(t.id).length);}
function taskLeaves(t){return children(t.id).length?descendants(t.id).filter(x=>x.kind!=='group'&&!children(x.id).length):t.kind==='group'?[]:[t];}
function derivedStatus(t){const items=taskLeaves(t);if(!children(t.id).length)return t.status;if(items.length&&items.every(x=>x.status==='Done'))return 'Done';if(items.some(x=>['In Progress','Review','Done'].includes(x.status)))return 'In Progress';if(items.some(x=>x.status==='Ready'))return 'Ready';return 'Backlog';}
function prerequisites(t){const ids=new Set(t.dependencies||[]),seen=new Set([t.id]);let p=taskById(t.parent);while(p&&!seen.has(p.id)){seen.add(p.id);for(const id of p.dependencies||[])ids.add(id);p=taskById(p.parent);}return [...ids];}
function blocked(t){return prerequisites(t).map(taskById).filter(Boolean).filter(d=>derivedStatus(d)!=='Done');}
function totalEffort(t){return taskLeaves(t).reduce((n,x)=>n+(Number(x.estimate)||0),0);}
function parentGroup(t){let x=t;const seen=new Set();while(x?.parent&&!seen.has(x.id)){seen.add(x.id);x=taskById(x.parent);}return x||t;}
function taskCode(id){return `CF-${String(id).padStart(3,'0')}`;}
function statusPill(s){return `<span class="status status-${slug(s)}">${esc(s)}</span>`;}
function disciplinePill(d){return `<span class="discipline discipline-${slug(d)}">${icon(d==='Dev'?'code':d==='Art'?'brush':d==='QA'?'shield':'people')}${esc(d)}</span>`;}
function priorityPill(p='Medium'){const level={Low:1,Medium:2,High:3}[p]||2;return `<span class="priority priority-${slug(p)}"><svg viewBox="0 0 12 12" aria-hidden="true">${[[1,4],[5,7],[9,10]].map(([x,h],i)=>`<rect x="${x}" y="${11-h}" width="2" height="${h}" rx=".5" fill="currentColor" stroke="none" opacity="${i<level?1:.25}"/>`).join('')}</svg>${esc(p)}</span>`;}
function tagClass(kind,value){return `tag-select ${kind}-${slug(value)}`;}
/* AI imports store [full brief, quoted evidence]; the evidence is the more useful one to show first. */
function taskReferences(t){const ids=t.sources.some(id=>id.startsWith('ai-'))?[...t.sources].reverse():t.sources;return ids.map(id=>state.sources.find(s=>s.id===id)).filter(Boolean);}
function cardReference(t){const refs=taskReferences(t);if(!refs.length)return '';return `<button class="card-reference" data-action="source" data-id="${esc(refs[0].id)}" aria-label="Open reference ${esc(refs[0].title)}">${icon('link')}<span>${esc(refs[0].title)}</span>${refs.length>1?`<small>+${refs.length-1}</small>`:''}</button>`;}
function ticketReferences(t){const refs=taskReferences(t);return `<aside class="ticket-refs" aria-label="References"><h3>References<span>${refs.length}</span></h3>${refs.map(s=>`<details class="ticket-ref" open><summary>${esc(s.title)}</summary><div class="ref-text">${esc(s.text)}</div>${(s.images||[]).map(im=>`<figure class="source-image"><img src="${esc(im.url)}" alt="${esc(im.caption)}" loading="lazy"><figcaption>${esc(im.caption)}</figcaption></figure>`).join('')}<button type="button" class="ref-open" data-action="source" data-id="${esc(s.id)}" data-return="${t.id}">Open full reference${icon('right')}</button></details>`).join('')||'<p class="ref-empty">No references yet.<br>This task was created manually.</p>'}</aside>`;}
function ownerHtml(owner){return `<span class="owner" title="${esc(owner)}"><span class="avatar">${owner==='Unassigned'?'–':esc(owner.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}</span><span class="owner-name">${esc(owner)}</span></span>`;}
function videoChips(videos,max=4){return `<span class="video-chips">${videos.slice(0,max).map(v=>`<span class="video-chip" title="${esc(VIDEO_NAMES[v])}">${esc(v)}</span>`).join('')}${videos.length>max?`<span class="video-chip">+${videos.length-max}</span>`:''}</span>`;}
function matches(t){const f=state.filters;const q=f.query.trim().toLowerCase();return(f.discipline==='All'||t.discipline===f.discipline)&&(f.video==='All'||t.videos.includes(f.video))&&(f.status==='All'||derivedStatus(t)===f.status)&&(!q||[t.title,t.description,t.id,taskCode(t.id),t.owner,...t.videos].join(' ').toLowerCase().includes(q));}
function relevant(t){return matches(t)||descendants(t.id).some(matches);}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function persist(){state.updated=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOk=true;}catch(e){storageOk=false;toast('Browser storage unavailable. Export a backup to keep your edits.');}}
function validateWorkspace(data){
 if(!data||data.version!==1||!Array.isArray(data.tasks)||!Array.isArray(data.sources))throw new Error('Choose a Briefboard workspace JSON exported from this demo.');
 validateBaseProjects(data);
 if(data.tasks.length>2000||data.sources.length>300)throw new Error('This demo supports up to 2,000 tasks and 300 source sections.');
 const ids=new Set();for(const t of data.tasks){if(typeof t.id!=='string'||!/^\d{3,6}$/.test(t.id)||ids.has(t.id))throw new Error('Task IDs must be unique numeric strings.');ids.add(t.id);if(typeof t.title!=='string'||!t.title.trim()||t.title.length>1000||!['task','group'].includes(t.kind)||!STATUSES.includes(t.status)||!['Art','Dev','QA','Mixed'].includes(t.discipline)||typeof t.owner!=='string'||!Array.isArray(t.videos)||t.videos.some(v=>!ALL_VIDEOS.includes(v))||!Array.isArray(t.sources)||!Array.isArray(t.criteria)||!Array.isArray(t.dependencies)||!Number.isFinite(t.estimate)||t.estimate<0||t.estimate>1000)throw new Error('A task has invalid fields. The workspace was not changed.');}
 const sourceIds=new Set();for(const s of data.sources){if(typeof s.id!=='string'||sourceIds.has(s.id)||typeof s.title!=='string'||typeof s.text!=='string')throw new Error('Invalid source section.');sourceIds.add(s.id);for(const im of s.images||[])if(!/^assets\/map-(manual|auto|short)\.png$/.test(im.url))throw new Error('Workspace image references are not supported.');}
 for(const t of data.tasks){if(t.parent!==null&&!ids.has(t.parent))throw new Error('A parent task is missing.');if(t.sources.some(s=>!sourceIds.has(s)))throw new Error('A source reference is missing.');if(t.dependencies.some(d=>!ids.has(d)))throw new Error('A dependency is missing.');let p=t;const seen=new Set();while(p){if(seen.has(p.id))throw new Error('Parent relationships contain a cycle.');seen.add(p.id);p=data.tasks.find(x=>x.id===p.parent);}}
 const visiting=new Set(),done=new Set();function visit(t){if(visiting.has(t.id))throw new Error('Task dependencies contain a cycle.');if(done.has(t.id))return;visiting.add(t.id);for(const d of t.dependencies)visit(data.tasks.find(x=>x.id===d));visiting.delete(t.id);done.add(t.id);}data.tasks.forEach(visit);
 return true;
}
async function init(){
 try{const r=await fetch('sources.json');if(!r.ok)throw Error('Source library could not load.');state.sources=await r.json();}catch(e){document.getElementById('app').innerHTML=`<div class="empty"><strong>Source library could not load</strong>Serve this folder using an HTTP server, then reload.</div>`;return;}
 try{const saved=localStorage.getItem(STORAGE_KEY);if(saved){const parsed=JSON.parse(saved);validateWorkspace(parsed);state={...clone(DEFAULT_STATE),...parsed,filters:{...DEFAULT_STATE.filters,...parsed.filters}};if(!['tree','board','streams','coverage','timeline','sources','bases'].includes(state.view))state.view='tree';if(!Array.isArray(state.collapsed))state.collapsed=[];}}catch(e){toast('Saved workspace could not load. The original demo is available.');}
 render();
}
function navButton(view,title,ico){return `<button class="nav-button ${state.view===view?'active':''}" data-action="view" data-view="${view}" title="${title}">${icon(ico)}<span>${title}</span>${view==='tree'?`<span class="counter">${leaves().length}</span>`:''}</button>`;}
function render(){
 const all=leaves(),done=all.filter(t=>t.status==='Done').length,active=all.filter(t=>t.status==='In Progress').length;
 const topGroups=state.tasks.filter(t=>t.parent===null&&t.kind==='group');
 document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-logo">${icon('logo')}</div><span>briefboard<span style="color:#bde781">.</span></span></div><div class="workspace"><span class="mini">S</span><div>Supercent Studio<small>Creative production</small></div>${icon('chevron')}</div><div class="nav-label">WORKSPACE</div>${navButton('tree','Task overview','grid')}${navButton('sources','Sources','folder')}${navButton('bases','Base project','folder')}<div class="nav-label">PROJECTS</div><button class="project-button" data-action="view" data-view="tree"><span class="dot"></span>2F Crusher Factory</button><div class="sidebar-bottom"><button class="nav-button" data-action="about" title="About this demo">${icon('info')}<span>About this demo</span></button><div class="profile"><span class="avatar">AL</span><div><strong>Alvin's workspace</strong><small>Local · v0.2</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><span>Workspace</span>${icon('right')}<span>Projects</span>${icon('right')}<b>Crusher Factory</b></div><div class="top-actions"><span class="save-indicator">${icon('cloud')}${storageOk?'Saved on this device':'Storage unavailable'}</span><button class="icon-button" data-action="about" title="Demo information">${icon('info')}</button></div></header><div class="page"><div class="eyebrow"><span class="dot"></span>CREATIVE PRODUCTION / BULLDOZER MASTER</div><div class="project-heading"><div><div class="title-line"><h1>2F Crusher Factory</h1><span class="demo-pill">DEMO WORKSPACE</span></div></div><div class="heading-buttons"><button class="button" data-action="import">${icon('upload')}Import brief</button><button class="button primary" data-action="new">${icon('plus')}New task</button></div></div><div class="summary"><div class="stat"><div class="stat-head">Tasks<span class="stat-icon">${icon('tree')}</span></div><div class="stat-bottom"><span class="stat-number">${all.length}</span><span class="stat-caption">${topGroups.length} groups</span></div></div><div class="stat"><div class="stat-head">In progress<span class="stat-icon orange">${icon('clock')}</span></div><div class="stat-bottom"><span class="stat-number">${active}</span></div></div><div class="stat"><div class="stat-head">Completed<span class="stat-icon green">${icon('check')}</span></div><div class="stat-bottom"><span class="stat-number">${done}<span style="font-size:15px;color:var(--muted);font-weight:500"> / ${all.length}</span></span><span class="stat-caption"><span class="progress-mini"><i style="width:${all.length?done/all.length*100:0}%"></i></span>${all.length?Math.round(done/all.length*100):0}%</span></div></div><div class="stat"><div class="stat-head">Video variants<span class="stat-icon blue">${icon('film')}</span></div><div class="stat-bottom"><span class="stat-number">08</span><span class="stat-caption">3 layouts</span></div></div></div>${state.view==='bases'?'':baseSummaryHtml()}<nav class="view-tabs" aria-label="Project views">${[['tree','Task tree','tree'],['board','Kanban','board'],['streams','Dev & Art','people'],['timeline','Timeline','timeline'],['coverage','Video coverage','film']].map(([v,l,i])=>`<button class="view-tab ${state.view===v?'active':''}" data-action="view" data-view="${v}">${icon(i)}${l}</button>`).join('')}</nav>${state.view==='bases'?'':toolbar()}<div id="view-content">${viewHtml()}</div><footer class="page-footer"><span>${icon('shield')}Demo estimates · saved locally</span><span><button data-action="export" class="subtle-button">${icon('download')}Export</button></span></footer></div></main></div>`;
 bindDrag();
}
function toolbar(){return `<div class="toolbar"><label class="search-box">${icon('search')}<input id="task-search" aria-label="Search tasks" value="${esc(state.filters.query)}" placeholder="Search…"><span class="kbd">/</span></label><select class="filter ${state.filters.discipline!=='All'?'selected-filter':''}" id="filter-discipline" aria-label="Filter discipline">${options(['All','Dev','Art','QA'],state.filters.discipline,'All disciplines')}</select><select class="filter ${state.filters.video!=='All'?'selected-filter':''}" id="filter-video" aria-label="Filter video"><option value="All">All videos</option>${ALL_VIDEOS.map(v=>`<option value="${v}" ${state.filters.video===v?'selected':''}>Video ${v}</option>`).join('')}</select><select class="filter ${state.filters.status!=='All'?'selected-filter':''}" id="filter-status" aria-label="Filter status">${options(['All',...STATUSES],state.filters.status,'All statuses')}</select>${state.view==='tree'?`<button class="subtle-button" data-action="expand" title="Expand or collapse all packages">${icon('expand')}<span>Expand</span></button>`:''}${Object.values(state.filters).some(x=>x!==''&&x!=='All')?'<button class="clear-filters" data-action="clear">Clear</button>':''}</div>`;}
function options(values,selected,allLabel){return values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v==='All'&&allLabel?allLabel:v)}</option>`).join('');}
function viewHtml(){switch(state.view){case'board':return boardHtml();case'streams':return streamsHtml();case'coverage':return coverageHtml();case'timeline':return timelineHtml();case'sources':return sourcesHtml();case'bases':return baseProjectsHtml();default:return treeHtml();}}
function emptyHtml(label='No tasks match these filters.'){return `<div class="empty"><strong>Room for a little clarity.</strong>${esc(label)}<br><button class="button" data-action="clear">Clear filters</button></div>`;}
function groupProgress(t){const ls=taskLeaves(t),done=ls.filter(x=>x.status==='Done').length;return `<span class="group-progress"><span class="progress-mini"><i style="width:${ls.length?done/ls.length*100:0}%"></i></span>${done}/${ls.length}</span>`;}
function treeHtml(){
 const roots=state.tasks.filter(t=>t.parent===null&&relevant(t));
 if(!roots.length)return emptyHtml();
 return `<section class="task-table" aria-label="Task hierarchy"><div class="table-head"><span>TASK NAME</span><span>STATUS</span><span class="discipline-col">DISCIPLINE</span><span class="owner-col">ASSIGNEE</span><span class="effort-col">EFFORT</span></div>${roots.map(t=>t.kind==='group'?groupHtml(t):taskRow(t)).join('')}<div class="table-footer"><span>${leaves().filter(matches).length} tasks</span><span>Effort: days</span></div></section>`;
}
function groupHtml(g){const filterActive=Object.values(state.filters).some(v=>v!==''&&v!=='All');const collapsed=state.collapsed.includes(g.id)&&!filterActive;const ls=taskLeaves(g).filter(matches);return `<div class="task-group ${collapsed?'collapsed':''}"><div class="group-row" role="button" tabindex="0" aria-expanded="${!collapsed}" data-action="toggle-group" data-id="${g.id}"><div class="group-name">${icon('chevron','chevron')}${icon('folder','group-icon')}<span class="task-id">${taskCode(g.id)}</span><strong>${esc(g.title)}</strong><span class="group-count">${ls.length}</span></div><span class="group-status">GROUP</span><span class="discipline-col">${disciplinePill('Mixed')}</span><span class="owner-col"></span><span class="effort-col">${groupProgress(g)}</span></div>${collapsed?'':children(g.id).filter(relevant).map(t=>t.kind==='group'?groupHtml(t):taskRow(t)).join('')+`<button class="add-row" data-action="new" data-parent="${g.id}">${icon('plus')}Add subtask</button>`}</div>`;}
function taskRow(t,depth=0){const hasChildren=children(t.id).length>0,collapsed=state.collapsed.includes(t.id);const sourceCount=t.sources.length;return `<div class="task-row ${depth?'nested-row':''}" data-action="detail" data-id="${t.id}" role="button" tabindex="0" aria-label="Open ${esc(t.title)}"><div class="task-name">${hasChildren?`<button class="icon-button" data-action="toggle-group" data-id="${t.id}" aria-label="Toggle subtasks">${icon(collapsed?'right':'chevron')}</button>`:`<button class="task-check ${t.status==='Done'?'checked':''}" data-action="complete" data-id="${t.id}" aria-label="${t.status==='Done'?'Reopen':'Complete'} ${esc(t.title)}">${t.status==='Done'?icon('check'):''}</button>`}<span class="task-name-text"><span class="task-title">${esc(t.title)}</span><span class="task-meta"><span>${taskCode(t.id)}</span><span>·</span>${videoChips(t.videos)}${sourceCount?`<span title="${sourceCount} source sections">${icon('link')}${sourceCount}</span>`:''}${hasChildren?`<span>· ${taskLeaves(t).length} subtasks</span>`:''}</span></span></div><span>${statusPill(derivedStatus(t))}</span><span class="discipline-col">${disciplinePill(t.discipline)}</span><span class="owner-col">${ownerHtml(t.owner)}</span><span class="effort effort-col">${totalEffort(t)}d</span></div>${hasChildren&&!collapsed?children(t.id).filter(relevant).map(x=>taskRow(x,depth+1)).join(''):''}`;}
function boardHtml(){const tasks=leaves().filter(matches);if(!tasks.length)return emptyHtml();return `<div class="kanban">${STATUSES.map(s=>`<section class="board-column" data-drop-status="${s}"><div class="column-head"><strong>${statusPill(s)}</strong><span class="column-count">${tasks.filter(t=>t.status===s).length}</span></div>${tasks.filter(t=>t.status===s).map(t=>`<article class="board-card" draggable="true" data-drag-id="${t.id}" data-action="detail" data-id="${t.id}" tabindex="0" role="button" aria-label="Open ${esc(t.title)}"><div class="card-top"><span class="task-id">${taskCode(t.id)}</span>${videoChips(t.videos,2)}</div><h3>${esc(t.title)}</h3><div class="card-tags">${disciplinePill(t.discipline)}${priorityPill(t.priority)}</div>${cardReference(t)}${blocked(t).length?`<span class="card-blocked">${icon('link')}${blocked(t).length} open prerequisite${blocked(t).length>1?'s':''}</span>`:''}<div class="card-bottom">${ownerHtml(t.owner)}<select class="${tagClass('status',t.status)}" data-tag="status" data-task-status="${t.id}" aria-label="Status for ${esc(t.title)}">${options(STATUSES,t.status)}</select></div></article>`).join('')}<button class="subtle-button" data-action="new" data-status="${s}">${icon('plus')}Add task</button></section>`).join('')}</div>`;}
function streamsHtml(){const tasks=leaves().filter(matches);if(!tasks.length)return emptyHtml();return `<div class="workstreams">${['Dev','Art','QA'].map(d=>`<section class="workstream"><div class="workstream-head">${disciplinePill(d)}<h2>${d==='Dev'?'Development':d==='Art'?'Art & assets':'Review & capture'}</h2><span>${tasks.filter(t=>t.discipline===d).length} tasks</span></div>${tasks.filter(t=>t.discipline===d).map(t=>`<div class="stream-task" data-action="detail" data-id="${t.id}" tabindex="0" role="button"><button class="task-check ${t.status==='Done'?'checked':''}" data-action="complete" data-id="${t.id}" aria-label="Toggle completion">${t.status==='Done'?icon('check'):''}</button><div><strong>${esc(t.title)}</strong><small>${taskCode(t.id)} · ${t.estimate}d · ${esc(t.owner)}</small><div style="margin-top:8px">${statusPill(t.status)}</div></div></div>`).join('')||'<div class="empty">No matching tasks.</div>'}</section>`).join('')}</div>`;}
function coverageHtml(){const groups=state.tasks.filter(t=>t.parent===null&&taskLeaves(t).some(matches));const cols=state.filters.video==='All'?ALL_VIDEOS:[state.filters.video];if(!groups.length)return emptyHtml();return `<div class="coverage"><table><thead><tr><th>TASK / VIDEO VARIANT</th>${cols.map(v=>`<th title="${esc(VIDEO_NAMES[v])}">VIDEO ${v}</th>`).join('')}</tr></thead><tbody>${groups.map(g=>`<tr class="section-row"><td colspan="${cols.length+1}">${taskCode(g.id)} · ${esc(g.title)}</td></tr>${taskLeaves(g).filter(matches).map(t=>`<tr><td data-action="detail" data-id="${t.id}" tabindex="0" role="button">${esc(t.title)}</td>${cols.map(v=>`<td>${t.videos.includes(v)?`<span class="coverage-mark ${t.status==='Done'?'done':''}" title="${esc(t.status)}">${icon('check')}</span>`:'<span style="color:#ddd">—</span>'}</td>`).join('')}</tr>`).join('')}`).join('')}</tbody></table></div>`;}
function computeSchedule(){
 const all=leaves(), result={},capacity={Dev:0,Art:0,QA:0,Mixed:0},pending=[...all];let rounds=0;
 while(pending.length&&rounds++<all.length+1){let advanced=false;for(let i=0;i<pending.length;){const t=pending[i];const deps=[...new Set(prerequisites(t).flatMap(id=>{const d=taskById(id);return d?taskLeaves(d).map(x=>x.id):[];}))];if(deps.every(id=>result[id])){const start=Math.max(capacity[t.discipline]||0,...deps.map(id=>result[id].end),0),end=start+Math.max(.25,Number(t.estimate)||.25);result[t.id]={start,end};capacity[t.discipline]=end;pending.splice(i,1);advanced=true;}else i++;}if(!advanced)break;}
 return {items:result,unresolved:pending,max:Math.max(20,...Object.values(result).map(s=>s.end))};
}
function workingDay(start,offset){const date=new Date(start+'T12:00:00');if(Number.isNaN(date.getTime()))return '';while(date.getDay()===0||date.getDay()===6)date.setDate(date.getDate()+1);for(let i=0;i<offset;i++){date.setDate(date.getDate()+1);while(date.getDay()===0||date.getDay()===6)date.setDate(date.getDate()+1);}return date.toLocaleDateString('en',{month:'short',day:'numeric'});}
function timelineHtml(){const s=computeSchedule();const groups=state.tasks.filter(t=>t.parent===null&&taskLeaves(t).some(matches));if(!groups.length)return emptyHtml();const horizon=Math.ceil(s.max),step=Math.ceil(horizon/20);const cols=Math.ceil(horizon/step);return `<div class="timeline-intro">${icon('info')}Tentative plan, calculated from sample person-day estimates and dependencies. Assumes one person per discipline and weekdays only. Status does not change capacity. This is not a committed deadline.</div><div class="schedule-control"><label for="schedule-start">Proposed start</label><input type="date" id="schedule-start" value="${esc(state.scheduleStart)}"><span>· ${horizon} working days · edit effort and prerequisites inside a task</span><button class="button" data-action="export-csv">${icon('download')}Export schedule</button></div>${s.unresolved.length?`<div class="dependency-warning">${s.unresolved.length} tasks could not be scheduled. Review prerequisite relationships.</div>`:''}<div class="timeline"><div class="timeline-header"><span>GROUP</span><div class="timeline-days" style="grid-template-columns:repeat(${cols},1fr)">${Array.from({length:cols},(_,i)=>`<span>${workingDay(state.scheduleStart,i*step)}</span>`).join('')}</div></div>${groups.map(g=>{const ls=taskLeaves(g).filter(matches),dates=ls.map(t=>s.items[t.id]).filter(Boolean);if(!dates.length)return '';const start=Math.min(...dates.map(d=>d.start)),end=Math.max(...dates.map(d=>d.end));return `<div class="timeline-row"><div class="timeline-label">${esc(g.title)}<small>${ls.length} tasks · ${workingDay(state.scheduleStart,Math.floor(start))} – ${workingDay(state.scheduleStart,Math.ceil(end)-1)}</small></div><div class="timeline-track" style="background-size:${100/cols}% 100%"><div class="timeline-bar ${ls.every(t=>t.discipline==='Art')?'art':ls.every(t=>t.discipline==='QA')?'qa':''}" style="left:${start/horizon*100}%;width:${(end-start)/horizon*100}%" title="${esc(g.title)}: ${start.toFixed(1)}–${end.toFixed(1)} working days">${esc(g.title)}</div></div></div>`;}).join('')}</div>`;}
function sourcesHtml(){const q=state.filters.query.toLowerCase().trim();const sources=state.sources.filter(s=>(!q||[s.title,s.text,s.file].join(' ').toLowerCase().includes(q))&&(state.filters.discipline==='All'&&state.filters.video==='All'&&state.filters.status==='All'||leaves().some(t=>matches(t)&&t.sources.includes(s.id))));if(!sources.length)return emptyHtml('No source sections match your search or linked-task filters.');return `<div class="sources-grid">${sources.map(s=>{const n=leaves().filter(t=>t.sources.includes(s.id)).length;return `<button class="source-card" data-action="source" data-id="${esc(s.id)}">${icon('file')}<h3>${esc(s.title)}</h3><p>${esc(s.text)}</p><div class="source-card-foot"><span>${n} linked task${n===1?'':'s'}${s.images?.length?` · ${s.images.length} diagrams`:''}</span>${icon('arrow')}</div></button>`;}).join('')}</div>`;}
function bindDrag(){document.querySelectorAll('[draggable=true]').forEach(card=>{card.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',card.dataset.dragId);e.dataTransfer.effectAllowed='move';});});document.querySelectorAll('[data-drop-status]').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drag-over');});col.addEventListener('dragleave',e=>{if(!col.contains(e.relatedTarget))col.classList.remove('drag-over');});col.addEventListener('drop',e=>{e.preventDefault();const t=taskById(e.dataTransfer.getData('text/plain'));if(t)changeStatus(t,col.dataset.dropStatus);});});}
function changeStatus(t,status){if(!STATUSES.includes(status)||children(t.id).length)return;t.status=status;persist();render();toast(`${taskCode(t.id)} moved to ${status}${status==='Done'&&blocked(t).length?' · prerequisites are still open':''}`);}
function showModal(html,wide=false){lastFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide===true?'wide':wide||''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">${html}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal input:not([type=checkbox]),.modal textarea,.modal button,.modal')?.focus(),20);}
function closeModal(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';activeModal=null;lastFocus?.isConnected&&lastFocus.focus();}
function modalHeader(title,sub){return `<header class="modal-head"><div><h2 id="dialog-title">${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></header>`;}
function detailModal(id){const t=taskById(id);if(!t)return;activeModal={type:'detail',id};const sub=children(id),excluded=new Set([id,...descendants(id).map(x=>x.id)]);let p=taskById(t.parent);while(p){excluded.add(p.id);p=taskById(p.parent);}showModal(`${modalHeader(taskCode(id)+' · '+t.title,`${parentGroup(t).title}${sub.length?' · status from subtasks':''}`)}<form id="task-form" data-id="${id}"><div class="modal-body ticket-body"><div class="ticket-main">${blocked(t).length?`<div class="dependency-warning">${icon('link')} ${blocked(t).length} open prerequisite${blocked(t).length>1?'s':''}: ${blocked(t).map(d=>esc(taskCode(d.id))).join(', ')}. </div>`:''}<div class="field"><label class="field-label" for="f-title">Task title</label><input class="form-title" id="f-title" required maxlength="240" value="${esc(t.title)}"></div><div class="field-grid"><div class="field"><label class="field-label" for="f-status">Status${sub.length?' (rollup)':''}</label><select id="f-status" class="${tagClass('status',derivedStatus(t))}" data-tag="status" ${sub.length?'disabled':''}>${options(STATUSES,derivedStatus(t))}</select></div><div class="field"><label class="field-label" for="f-discipline">Discipline</label><select id="f-discipline" class="${tagClass('discipline',t.discipline)}" data-tag="discipline">${options(['Dev','Art','QA'],t.discipline)}</select></div></div><div class="field-grid"><div class="field"><label class="field-label" for="f-owner">Assignee</label><input id="f-owner" value="${esc(t.owner)}" maxlength="60"></div><div class="field"><label class="field-label" for="f-priority">Priority</label><select id="f-priority" class="${tagClass('priority',t.priority)}" data-tag="priority">${options(['Low','Medium','High'],t.priority)}</select></div></div><div class="field"><span class="field-label">Applies to videos</span>${videoToggles(t.videos)}</div><div class="field"><label class="field-label" for="f-description">Scope</label><textarea id="f-description" rows="3">${esc(t.description)}</textarea></div><div class="field"><label class="field-label" for="f-criteria">Done when · one per line</label><textarea id="f-criteria" rows="3">${esc(t.criteria.join('\n'))}</textarea></div><details class="task-more"><summary>More: effort, prerequisites, notes</summary><div class="field-grid"><div class="field"><label class="field-label" for="f-estimate">Effort · person-days${sub.length?' (leaf tasks determine schedule)':''}</label><input type="number" min="0.25" max="1000" step="0.25" id="f-estimate" required value="${t.estimate||1}"></div></div><div class="field" style="margin-top:20px"><label class="field-label" for="f-deps">Prerequisites (⌘ / Ctrl to select)</label><select multiple size="4" id="f-deps">${state.tasks.filter(x=>x.kind==='task'&&!excluded.has(x.id)).map(x=>`<option value="${x.id}" ${t.dependencies.includes(x.id)?'selected':''}>${taskCode(x.id)} · ${esc(x.title)}</option>`).join('')}</select></div>${sub.length?`<div class="section-title">Subtasks</div><div class="subtask-links">${sub.map(x=>`<button type="button" data-action="detail" data-id="${x.id}">${esc(x.title)} ${icon('right')}</button>`).join('')}</div>`:''}<div class="field" style="margin-top:20px"><label class="field-label" for="f-notes">Notes</label><textarea id="f-notes" placeholder="Decisions, blockers, or questions to clarify…" rows="2">${esc(t.notes)}</textarea></div></details><div id="form-error" class="import-error" role="alert"></div></div>${ticketReferences(t)}</div><footer class="modal-foot"><div><button type="button" class="danger-link" data-action="delete" data-id="${id}">Delete</button><button type="button" class="subtle-button" data-action="new" data-parent="${id}">${icon('plus')}Subtask</button></div><div><button type="button" class="button" data-action="close">Cancel</button><button class="button primary" type="submit">Save</button></div></footer></form>`,'ticket');}
function videoToggles(videos){return `<div class="video-toggle">${ALL_VIDEOS.map(v=>`<label title="${esc(VIDEO_NAMES[v])}"><input type="checkbox" name="videos" value="${v}" ${videos.includes(v)?'checked':''}>${v}</label>`).join('')}</div>`;}
function newModal(parent=null,status='Backlog'){activeModal={type:'new'};const p=taskById(parent);showModal(`${modalHeader(p?'Add a subtask':'Create a task',p?`Under ${taskCode(p.id)} · ${p.title}`:'Give the next piece of work a clear home.')}<form id="new-form"><div class="modal-body"><div class="field"><label for="n-title" class="field-label">Task title</label><input id="n-title" required maxlength="240" placeholder="e.g. Configure customer queue camera"></div><div class="field"><label for="n-parent" class="field-label">Parent task / work package</label><select id="n-parent"><option value="">No parent · standalone task</option>${state.tasks.map(t=>`<option value="${t.id}" ${parent===t.id?'selected':''}>${taskCode(t.id)} · ${esc(t.title)}</option>`).join('')}</select></div><div class="field-grid"><div class="field"><label for="n-discipline" class="field-label">Discipline</label><select id="n-discipline">${options(['Dev','Art','QA'],p?.discipline==='Art'?'Art':'Dev')}</select></div><div class="field"><label for="n-status" class="field-label">Status</label><select id="n-status">${options(STATUSES,status)}</select></div></div><div class="field"><label for="n-description" class="field-label">Description</label><textarea id="n-description" placeholder="What should be delivered?" rows="3"></textarea></div><div class="field"><span class="field-label">Applies to videos</span>${videoToggles(p?.videos?.length?p.videos:ALL_VIDEOS)}</div><div class="field"><label for="n-estimate" class="field-label">Tentative effort · person-days</label><input type="number" id="n-estimate" min="0.25" max="1000" step="0.25" value="1" required></div><div class="field"><span class="field-label">Link source sections</span><div class="source-select">${state.sources.map(s=>`<label><input type="checkbox" name="sources" value="${esc(s.id)}" ${p?.sources.includes(s.id)?'checked':''}>${esc(s.title)}</label>`).join('')}</div></div><div id="form-error" class="import-error" role="alert"></div></div><footer class="modal-foot"><small>You can add criteria and dependencies after creation.</small><div><button type="button" class="button" data-action="close">Cancel</button><button class="button primary" type="submit">Create task</button></div></footer></form>`);}
function sourceModal(id,returnId=null){const s=state.sources.find(x=>x.id===id);if(!s)return;activeModal={type:'source',id,returnId};showModal(`${modalHeader(s.title,s.file||'Imported source')}<div class="modal-body"><p class="detail-note" style="margin-bottom:12px">${s.imported?'Imported source':'Original brief'}</p><div class="source-excerpt">${esc(s.text)}</div>${(s.images||[]).map(im=>`<figure class="source-image"><img src="${esc(im.url)}" alt="${esc(im.caption)}" loading="lazy"><figcaption>${esc(im.caption)}</figcaption></figure>`).join('')}<p class="source-warning">Videos and other artwork: see the original brief.</p></div><footer class="modal-foot"><small>${leaves().filter(t=>t.sources.includes(id)).length} linked tasks</small><div>${!s.imported?'<a class="button" href="source-brief.txt" download>Download brief text</a>':''}<button class="button primary" data-action="${returnId?'detail':'close'}" ${returnId?`data-id="${returnId}"`:''}>${returnId?'Back to task':'Done'}</button></div></footer>`,true);}
function aboutModal(){activeModal={type:'about'};showModal(`${modalHeader('A clear home for scattered work.','Briefboard · first working demo')}<div class="modal-body"><p class="detail-note">Built from your local 2F Crusher Factory HTML brief. Source text is real; task decomposition, sample statuses, effort and dates are proposed planning data.</p><ul class="about-list"><li>Task tree, Kanban, Dev/Art, timeline and video coverage use the same tasks.</li><li>Edits save in this browser on this device. Export JSON for backup or transfer.</li><li>HTML, Markdown and text imports create editable drafts using headings and bullets. There is no server AI or direct Google Slides connection.</li><li>Workspace JSON import restores your exported plan. It replaces the current local workspace after confirmation.</li><li>Source links open excerpts and available diagrams; the original source files are untouched.</li></ul><div class="divider"></div><p class="detail-note">No accounts, live team synchronization, notifications or automatic deadlines are included in this version.</p></div><footer class="modal-foot"><button class="danger-link" data-action="reset">Reset demo data</button><div><button class="button" data-action="export">Export</button><button class="button primary" data-action="close">Got it</button></div></footer>`);}
function deleteModal(id){const t=taskById(id),n=descendants(id).length;showModal(`${modalHeader('Delete this task?',taskCode(id)+' · '+t.title)}<div class="modal-body"><p class="detail-note">${n?`This also deletes ${n} subtasks. `:''}References to these tasks will be removed from prerequisites. You can export the workspace before deleting.</p></div><footer class="modal-foot"><button class="button" data-action="export">Export backup</button><div><button class="button" data-action="detail" data-id="${id}">Keep task</button><button class="button danger" data-action="confirm-delete" data-id="${id}">Delete${n?' task and subtasks':''}</button></div></footer>`);}
function importModal(){importDraft=null;activeModal={type:'import'};showModal(`${modalHeader('Import brief','Review before adding.')}<div class="modal-body"><label class="upload-zone">${icon('upload')}<strong>Choose file</strong><small>HTML · MD · TXT · JSON · 5 MB</small><input type="file" id="import-file" accept=".html,.htm,.md,.txt,.json"></label><p class="import-note">For Google Slides, paste exported slide text below. This demo extracts headings and bullets locally; it does not interpret linked files or images. Suggested tasks need your review.</p><div class="field"><label class="field-label" for="import-title">Source name</label><input id="import-title" value="Imported brief" maxlength="150"></div><div class="field"><label class="field-label" for="import-text">Brief text</label><textarea id="import-text" rows="6" placeholder="# Map and Camera&#10;- Setup map for videos 001, 002, 005, 006&#10;- Configure Simulator camera for videos 005, 006"></textarea></div><div id="import-error" class="import-error" role="alert"></div><div id="import-review" class="import-preview"></div></div><footer class="modal-foot"><small id="import-summary">Existing tasks stay.</small><div><button class="button" data-action="close">Cancel</button><button class="button primary" id="import-submit" data-action="generate">Generate draft ${icon('arrow')}</button></div></footer>`,true);}
function classify(text){if(/test|review|verif|capture validation|qa\b/i.test(text))return 'QA';if(/model|texture|asset|design|art\b|layout|map assembly|illustration/i.test(text)&&!/implement|integrat|controller|logic/i.test(text))return 'Art';return 'Dev';}
function extractDraft(raw,title){
 let items=[],text=raw.trim(),section='Imported tasks';
 if(/<\s*(?:!doctype|html|body|h[1-6]|p|div|ul|article)\b/i.test(raw)){
  const doc=new DOMParser().parseFromString(raw,'text/html');doc.querySelectorAll('script,style,nav,header,footer').forEach(n=>n.remove());
  const nodes=[...doc.body.querySelectorAll('h1,h2,h3,h4,h5,h6,p,li,tr')];const eng=nodes.findIndex(n=>n.textContent.trim()==='ENG');const selected=eng>=0?nodes.slice(eng+1):nodes;text=selected.map(n=>n.textContent.trim()).filter(Boolean).join('\n\n');
  for(const n of selected){const value=n.textContent.replace(/\s+/g,' ').trim();if(!value||n.matches('li')&&n.parentElement?.closest('li')||n.matches('p')&&n.closest('li'))continue;if(/^H[1-6]$/.test(n.tagName)){section=value;continue;}if(value.length>=12)items.push({section,text:value});}
 }else{
  for(const line of text.split(/\n/)){const v=line.trim();if(!v)continue;const head=v.match(/^#{1,6}\s+(.+)/);if(head){section=head[1];continue;}const clean=v.replace(/^[-*•]\s+|^\d+[.)]\s+/,'');if(clean.length>=8)items.push({section,text:clean});}
 }
 const seen=new Set();items=items.filter(x=>{const key=x.text.toLowerCase().replace(/\s+/g,' ').trim();if(seen.has(key))return false;seen.add(key);return true;});
 const explicitVideos=value=>{const out=new Set();for(const m of value.matchAll(/\b00[1-8]\b/g))out.add(m[0]);for(const m of value.matchAll(/\b(00[1-8])\s*[–—-]\s*(00[1-8])\b/g))for(let n=+m[1];n<=+m[2];n++)out.add(String(n).padStart(3,'0'));return [...out].sort();};
 return {title,text,items:items.slice(0,80).map(x=>{const candidate=x.text.length>120?x.text.slice(0,117)+'…':x.text;return {...x,title:candidate,discipline:classify(x.section+' '+x.text),videos:explicitVideos(x.text),selected:true};}),total:items.length};
}
async function handleImportFile(file){if(!file)return;if(file.size>5*1024*1024){document.getElementById('import-error').textContent='Choose a file smaller than 5 MB.';return;}try{const raw=await file.text();document.getElementById('import-title').value=file.name;if(/\.json$/i.test(file.name)){const data=JSON.parse(raw);validateWorkspace(data);importDraft={workspace:data};document.getElementById('import-text').value='';document.getElementById('import-review').innerHTML=`<div class="evidence"><strong>Restore workspace: ${esc(data.project||'Crusher Factory')}</strong><p>${data.tasks.filter(t=>t.kind==='task').length} tasks · ${data.sources.length} source sections</p><p>This replaces the current local plan. Export a backup first if you want to keep it.</p></div>`;document.getElementById('import-submit').dataset.action='restore';document.getElementById('import-submit').textContent='Replace & restore';document.getElementById('import-summary').textContent='Restoring replaces tasks, edits, statuses and sources.';document.getElementById('import-error').textContent='';}else{document.getElementById('import-text').value=raw;importDraft=null;document.getElementById('import-review').innerHTML='';document.getElementById('import-submit').dataset.action='generate';document.getElementById('import-submit').textContent='Generate draft →';document.getElementById('import-error').textContent='';}}catch(e){document.getElementById('import-error').textContent=e.message||'The file could not be read.';}}
function generateDraft(){const raw=document.getElementById('import-text').value.trim(),title=document.getElementById('import-title').value.trim()||'Imported brief';if(!raw){document.getElementById('import-error').textContent='Choose a brief file or paste text first.';return;}if(raw.length>5*1024*1024){document.getElementById('import-error').textContent='This demo supports source text up to 5 MB.';return;}importDraft=extractDraft(raw,title);if(!importDraft.items.length){document.getElementById('import-error').textContent='No task candidates found. Add headings and requirement lines to the brief.';return;}document.getElementById('import-error').textContent='';document.getElementById('import-review').innerHTML=`<p class="import-note"><strong>Review ${importDraft.items.length} draft candidates${importDraft.total>80?' (first 80 shown)':''}.</strong> Edit titles, change discipline, or uncheck lines that are context. Unspecified video scope stays empty.</p>${importDraft.items.map((x,i)=>`<div class="import-item"><input type="checkbox" data-draft-index="${i}" checked aria-label="Include draft ${i+1}"><div><input type="text" data-draft-title="${i}" value="${esc(x.title)}" aria-label="Draft task title ${i+1}"><small>${esc(x.section)} · videos: ${x.videos.length?x.videos.join(', '):'unspecified'}</small></div><select class="filter" data-draft-discipline="${i}" aria-label="Draft discipline ${i+1}">${options(['Dev','Art','QA'],x.discipline)}</select></div>`).join('')}`;document.getElementById('import-submit').dataset.action='add-draft';document.getElementById('import-submit').textContent='Add selected tasks';document.getElementById('import-summary').textContent='Drafts will be grouped under their source headings.';}
function nextId(){return String(Math.max(0,...state.tasks.map(t=>Number(t.id)))+1).padStart(3,'0');}
function newTaskObject(title,parent,discipline,videos,sourceIds,description='',kind='task'){return {id:nextId(),title,parent,kind,discipline,videos,description,sources:sourceIds,criteria:[],dependencies:[],estimate:kind==='group'?0:1,status:'Backlog',owner:'Unassigned',priority:'Medium',notes:''};}
function addDraft(){if(!importDraft?.items)return;const review=document.getElementById('import-review');const selected=importDraft.items.map((x,i)=>({...x,selected:review.querySelector(`[data-draft-index="${i}"]`).checked,title:review.querySelector(`[data-draft-title="${i}"]`).value.trim(),discipline:review.querySelector(`[data-draft-discipline="${i}"]`).value})).filter(x=>x.selected);if(!selected.length||selected.some(x=>!x.title)){document.getElementById('import-error').textContent='Select at least one draft and give every selected task a title.';return;}
 const sourceId='import-'+Date.now().toString(36);state.sources.push({id:sourceId,title:importDraft.title,text:importDraft.text,file:importDraft.title,images:[],imported:true});
 const top=newTaskObject(importDraft.title,null,'Mixed',[],[sourceId],'Imported draft candidates. Review scope and acceptance criteria before production.','group');state.tasks.push(top);const sections=new Map();for(const x of selected){let parent=top.id;if(x.section!=='Imported tasks'){if(!sections.has(x.section)){const g=newTaskObject(x.section,top.id,'Mixed',[],[sourceId],'','group');state.tasks.push(g);sections.set(x.section,g.id);}parent=sections.get(x.section);}const t=newTaskObject(x.title,parent,x.discipline,x.videos,[sourceId],x.text);t.notes='Imported draft. Confirm scope, dependencies, effort and completion criteria.';state.tasks.push(t);}state.view='tree';state.filters=clone(DEFAULT_STATE.filters);persist();closeModal();render();toast(`Added ${selected.length} draft tasks and linked their source.`);}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportWorkspace(){download('briefboard-crusher-workspace.json',JSON.stringify({...state,exported:new Date().toISOString()},null,2),'application/json');toast('Workspace exported, including edits and source text.');}
function exportCsv(){const s=computeSchedule();const csvCell=v=>{const value=String(v??'');return '"'+(/^[=+@-]/.test(value)?"'":'')+value.replaceAll('"','""')+'"';};const rows=[['ID','Task','Discipline','Assignee','Effort (person-days)','Status','Prerequisites','Proposed start','Proposed finish'],...leaves().filter(matches).map(t=>{const d=s.items[t.id];return[taskCode(t.id),t.title,t.discipline,t.owner,t.estimate,t.status,t.dependencies.map(taskCode).join('; '),d?workingDay(state.scheduleStart,Math.floor(d.start)):'Unresolved',d?workingDay(state.scheduleStart,Math.ceil(d.end)-1):'Unresolved'];})];download('briefboard-tentative-schedule.csv',rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Tentative schedule exported.');}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-action]');if(!button)return;if(e.target.closest('select,input,textarea,a')&&!button.matches('a'))return;
 const {action,id,view,parent,status}=button.dataset;
 switch(action){
  case'view':state.view=view;persist();render();break;
  case'toggle-group':state.collapsed=state.collapsed.includes(id)?state.collapsed.filter(x=>x!==id):[...state.collapsed,id];persist();render();break;
  case'expand':{const gs=state.tasks.filter(t=>children(t.id).length);state.collapsed=gs.some(g=>state.collapsed.includes(g.id))?[]:gs.map(g=>g.id);persist();render();break;}
  case'clear':state.filters=clone(DEFAULT_STATE.filters);persist();render();break;
  case'detail':detailModal(id);break;
  case'complete':{const t=taskById(id);if(t)changeStatus(t,t.status==='Done'?'Ready':'Done');break;}
  case'new':newModal(parent||null,status||'Backlog');break;
  case'close':closeModal();break;
  case'source':sourceModal(id,button.dataset.return||null);break;
  case'about':aboutModal();break;
  case'export':exportWorkspace();break;
  case'export-csv':exportCsv();break;
  case'import':importModal();break;
  case'generate':generateDraft();break;
  case'add-draft':addDraft();break;
  case'restore':if(importDraft?.workspace){const saved=importDraft.workspace;validateWorkspace(saved);state={...clone(DEFAULT_STATE),...clone(saved),view:'tree',filters:clone(DEFAULT_STATE.filters)};persist();closeModal();render();toast('Workspace restored on this device.');}break;
  case'delete':deleteModal(id);break;
  case'confirm-delete':{const ids=new Set([id,...descendants(id).map(x=>x.id)]);state.tasks=state.tasks.filter(t=>!ids.has(t.id));for(const t of state.tasks)t.dependencies=t.dependencies.filter(d=>!ids.has(d));persist();closeModal();render();toast(`Deleted ${ids.size} task${ids.size>1?'s':''}.`);break;}
  case'reset':showModal(`${modalHeader('Reset this demo?','Your local edits will be replaced by the original sample plan.')}<div class="modal-body"><p class="detail-note">Export the workspace first if you want to keep your changes. The original brief stays untouched.</p></div><footer class="modal-foot"><button class="button" data-action="export">Export backup</button><div><button class="button" data-action="close">Keep changes</button><button class="button danger" data-action="confirm-reset">Reset demo</button></div></footer>`);break;
  case'confirm-reset':{const sources=state.sources.filter(s=>!s.imported);state=clone(DEFAULT_STATE);state.sources=sources;persist();closeModal();render();toast('Original demo restored.');break;}
 }
});
document.addEventListener('input',e=>{
 if(e.target.id==='task-search'){const pos=e.target.selectionStart;state.filters.query=e.target.value;persist();render();const el=document.getElementById('task-search');el.focus();el.setSelectionRange(pos,pos);}
 if(['import-text','import-title'].includes(e.target.id)&&importDraft){importDraft=null;document.getElementById('import-review').innerHTML='';document.getElementById('import-submit').dataset.action='generate';document.getElementById('import-submit').textContent='Generate draft →';}
});
document.addEventListener('change',e=>{if(e.target.dataset?.tag)e.target.className=tagClass(e.target.dataset.tag,e.target.value);});
document.addEventListener('change',e=>{
 if(e.target.id.startsWith('filter-')){const name=e.target.id.replace('filter-','');state.filters[name]=e.target.value;persist();render();}
 if(e.target.dataset.taskStatus){const t=taskById(e.target.dataset.taskStatus);if(t)changeStatus(t,e.target.value);}
 if(e.target.id==='import-file')handleImportFile(e.target.files[0]);
 if(e.target.id==='schedule-start'){if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)){state.scheduleStart=e.target.value;persist();render();}}
});
document.addEventListener('submit',e=>{
 if(!['task-form','new-form'].includes(e.target.id))return;e.preventDefault();const f=e.target;
 const val=id=>document.getElementById(id).value.trim();
 const videos=[...f.querySelectorAll('input[name=videos]:checked')].map(x=>x.value);
 if(f.id==='task-form'){
  const t=taskById(f.dataset.id),backup=clone(t);Object.assign(t,{title:val('f-title'),status:children(t.id).length?t.status:val('f-status'),discipline:val('f-discipline'),priority:val('f-priority'),owner:val('f-owner')||'Unassigned',estimate:Number(val('f-estimate')),videos,description:val('f-description'),criteria:val('f-criteria').split('\n').map(x=>x.trim()).filter(Boolean),dependencies:[...document.getElementById('f-deps').selectedOptions].map(x=>x.value),notes:val('f-notes')});
  try{validateWorkspace(state);const unresolved=computeSchedule().unresolved;if(unresolved.length)throw Error('These prerequisites create an unschedulable parent/subtask relationship. Choose other prerequisite tasks.');}catch(err){Object.assign(t,backup);document.getElementById('form-error').textContent=err.message;return;}
  persist();closeModal();render();toast(`${taskCode(t.id)} saved across all views.`);
 }else{
  const t=newTaskObject(val('n-title'),val('n-parent')||null,val('n-discipline'),videos,[...f.querySelectorAll('input[name=sources]:checked')].map(x=>x.value),val('n-description'));t.status=val('n-status');t.estimate=Number(val('n-estimate'));state.tasks.push(t);try{validateWorkspace(state);}catch(err){state.tasks.pop();document.getElementById('form-error').textContent=err.message;return;}if(t.parent)state.collapsed=state.collapsed.filter(x=>x!==t.parent);state.filters=clone(DEFAULT_STATE.filters);persist();closeModal();render();toast(`${taskCode(t.id)} created${t.parent?' as a subtask':''}.`);
 }
});
document.addEventListener('keydown',e=>{
 const modal=document.querySelector('.modal');if(e.key==='Escape'&&modal){closeModal();return;}
 if(modal&&e.key==='Tab'){const els=[...modal.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
 if(e.key==='/'&&!modal&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();document.getElementById('task-search')?.focus();}
 if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]:not(button)')){e.preventDefault();e.target.click();}
});
init();
